import unittest

from solution import score_gesture_plan


class ScoreGesturePlanTests(unittest.TestCase):
    def test_empty_inputs(self):
        self.assertEqual(score_gesture_plan([]), (0, 0))
        self.assertEqual(score_gesture_plan(()), (0, 0))

    def test_scores_all_outcome_directions(self):
        rounds = [("stone", "low"), ["sheet", "high"], ("shears", "mid")]
        # Direct: stone draw (5), shears beats sheet (12), sheet loses (2).
        # Directed: shears loses (3), shears wins (12), shears draws (7).
        self.assertEqual(score_gesture_plan(rounds), (19, 22))

    def test_complete_direct_mapping_and_accumulation(self):
        rounds = [
            ("stone", "low"), ("stone", "mid"), ("stone", "high"),
            ("sheet", "low"), ("sheet", "mid"), ("sheet", "high"),
            ("shears", "low"), ("shears", "mid"), ("shears", "high"),
        ]
        self.assertEqual(score_gesture_plan(rounds), (60, 60))

    def test_input_is_unchanged(self):
        rounds = [["stone", "high"], ["shears", "low"]]
        before = [["stone", "high"], ["shears", "low"]]
        score_gesture_plan(rounds)
        self.assertEqual(rounds, before)

    def test_wrong_outer_and_row_container_types(self):
        for value in (None, "stone", {"stone": "low"}, iter([])):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    score_gesture_plan(value)
        for row in ("stone", {"stone": "low"}, None):
            with self.subTest(row=row):
                with self.assertRaises(TypeError):
                    score_gesture_plan([row])

    def test_bad_lengths_and_symbols(self):
        for rounds in ([[]], [["stone"]], [["stone", "low", "extra"]], [["rock", "low"]], [["stone", "LOW"]], [[1, "low"]], [["stone", None]]):
            with self.subTest(rounds=rounds):
                with self.assertRaises(ValueError):
                    score_gesture_plan(rounds)


if __name__ == "__main__":
    unittest.main()

